40	import static org.apache.hudi.common.util.ValidationUtils.checkArgument;
41	
42	public class RollbackUtils {
43	
44	  private static final Logger LOG = LoggerFactory.getLogger(RollbackUtils.class);
45	
46	  /**
47	   * Get Latest version of Rollback plan corresponding to a clean instant.
48	   *
49	   * @param metaClient      Hoodie Table Meta Client
50	   * @param rollbackInstant Instant referring to rollback action
51	   * @return Rollback plan corresponding to rollback instant
52	   * @throws IOException
53	   */
54	  public static HoodieRollbackPlan getRollbackPlan(HoodieTableMetaClient metaClient, HoodieInstant rollbackInstant)
55	      throws IOException {
56	    // TODO: add upgrade step if required.
57	    final HoodieInstant requested = metaClient.getInstantGenerator().getRollbackRequestedInstant(rollbackInstant);
58	    return TimelineMetadataUtils.deserializeAvroMetadata(
59	        metaClient.getActiveTimeline().readRollbackInfoAsBytes(requested).get(), HoodieRollbackPlan.class);
60	  }
61	
62	  static Map<HoodieLogBlock.HeaderMetadataType, String> generateHeader(String instantToRollback, String rollbackInstantTime) {
63	    // generate metadata
64	    Map<HoodieLogBlock.HeaderMetadataType, String> header = new HashMap<>(3);
65	    header.put(HoodieLogBlock.HeaderMetadataType.INSTANT_TIME, rollbackInstantTime);
66	    header.put(HoodieLogBlock.HeaderMetadataType.TARGET_INSTANT_TIME, instantToRollback);
67	    header.put(HoodieLogBlock.HeaderMetadataType.COMMAND_BLOCK_TYPE,
68	        String.valueOf(HoodieCommandBlock.HoodieCommandBlockTypeEnum.ROLLBACK_BLOCK.ordinal()));
69	    return header;
70	  }
71	
72	  /**
73	   * Helper to merge 2 rollback-stats for a given partition.
74	   *
75	   * @param stat1 HoodieRollbackStat
76	   * @param stat2 HoodieRollbackStat
77	   * @return Merged HoodieRollbackStat
78	   */
79	  static HoodieRollbackStat mergeRollbackStat(HoodieRollbackStat stat1, HoodieRollbackStat stat2) {
80	    checkArgument(stat1.getPartitionPath().equals(stat2.getPartitionPath()));
81	    final List<String> successDeleteFiles = new ArrayList<>();
82	    final List<String> failedDeleteFiles = new ArrayList<>();
83	    final Map<StoragePathInfo, Long> commandBlocksCount = new HashMap<>();
84	    final Map<String, Long> logFilesFromFailedCommit = new HashMap<>();
85	    Option.ofNullable(stat1.getSuccessDeleteFiles()).ifPresent(successDeleteFiles::addAll);
86	    Option.ofNullable(stat2.getSuccessDeleteFiles()).ifPresent(successDeleteFiles::addAll);
87	    Option.ofNullable(stat1.getFailedDeleteFiles()).ifPresent(failedDeleteFiles::addAll);
88	    Option.ofNullable(stat2.getFailedDeleteFiles()).ifPresent(failedDeleteFiles::addAll);
89	    Option.ofNullable(stat1.getCommandBlocksCount()).ifPresent(commandBlocksCount::putAll);
90	    Option.ofNullable(stat2.getCommandBlocksCount()).ifPresent(commandBlocksCount::putAll);
91	    Option.ofNullable(stat1.getLogFilesFromFailedCommit()).ifPresent(logFilesFromFailedCommit::putAll);
92	    Option.ofNullable(stat2.getLogFilesFromFailedCommit()).ifPresent(logFilesFromFailedCommit::putAll);
93	    return new HoodieRollbackStat(stat1.getPartitionPath(), successDeleteFiles, failedDeleteFiles, commandBlocksCount, logFilesFromFailedCommit);
94	  }
95	
96	}
