68	  public MarkerBasedRollbackStrategy(HoodieTable<?, ?, ?, ?> table, HoodieEngineContext context, HoodieWriteConfig config, String instantTime) {
69	    this.table = table;
70	    this.context = context;
71	    this.basePath = table.getMetaClient().getBasePath().toString();
72	    this.config = config;
73	    this.instantTime = instantTime;
74	  }
75	
76	  @Override
77	  public List<HoodieRollbackRequest> getRollbackRequests(HoodieInstant instantToRollback) {
78	    try {
79	      List<String> markerPaths = MarkerBasedRollbackUtils.getAllMarkerPaths(
80	          table, context, instantToRollback.requestedTime(), config.getRollbackParallelism());
81	      int parallelism = Math.max(Math.min(markerPaths.size(), config.getRollbackParallelism()), 1);
82	      return context.map(markerPaths, markerFilePath -> {
83	        String typeStr = markerFilePath.substring(markerFilePath.lastIndexOf(".") + 1);
84	        IOType type = IOType.valueOf(typeStr);
85	        String filePathStr = WriteMarkers.stripMarkerSuffix(markerFilePath);
86	        StoragePath filePath = new StoragePath(basePath, filePathStr);
87	        String partitionPath = FSUtils.getRelativePartitionPath(new StoragePath(basePath), filePath.getParent());
88	        String fileId = FSUtils.getFileIdFromFilePath(filePath);
89	
90	        switch (type) {
91	          case MERGE:
92	          case CREATE:
93	            return createRollbackRequestForCreateAndMerge(fileId, partitionPath, filePath, instantToRollback);
94	          case APPEND:
95	            return createRollbackRequestForAppend(fileId, partitionPath, filePath, instantToRollback, filePathStr);
96	          default:
97	            throw new HoodieRollbackException("Unknown marker type, during rollback of " + instantToRollback);
98	        }
99	      }, parallelism);
100	    } catch (Exception e) {
101	      throw new HoodieRollbackException("Error rolling back using marker files written for " + instantToRollback, e);
102	    }
103	  }
